{
  "items": [
    {
      "name": "MvPolynomial.natDegree_optionEquivLeft",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial (Option σ) R),\n  ((MvPolynomial.optionEquivLeft R σ) p).natDegree = MvPolynomial.degreeOf none p"
    },
    {
      "name": "MvPolynomial.finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) →\n  [inst : CommSemiring R] → (n : ℕ) → MvPolynomial (Fin (n + 1)) R ≃ₐ[R] Polynomial (MvPolynomial (Fin n) R)"
    },
    {
      "name": "MvPolynomial.optionEquivLeft",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) → (S₁ : Type v) → [inst : CommSemiring R] → MvPolynomial (Option S₁) R ≃ₐ[R] Polynomial (MvPolynomial S₁ R)"
    },
    {
      "name": "Polynomial.mapAlgEquiv_toAlgHom",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u} {A : Type z} {B : Type u_2} [inst : CommSemiring R] [inst_1 : Semiring A] [inst_2 : Semiring B]\n  [inst_3 : Algebra R A] [inst_4 : Algebra R B] (f : A ≃ₐ[R] B), ↑(Polynomial.mapAlgEquiv f) = Polynomial.mapAlgHom ↑f"
    },
    {
      "name": "MvPolynomial.degreeOf_eq_natDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (a : σ) (p : MvPolynomial σ R),\n  MvPolynomial.degreeOf a p =\n    ((MvPolynomial.optionEquivLeft R { b // b ≠ a })\n        ((MvPolynomial.rename ⇑(Equiv.optionSubtypeNe a).symm) p)).natDegree"
    }
  ]
}
